import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("DATABASE_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String tenantId = req.getHeader("X-Tenant-ID");
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        if (tenantId == null || tenantId.isEmpty()) {
            resp.sendError(401, "Missing tenant context");
            return;
        }

        // Validate report type against allowed list
        String[] allowedTypes = {"sales", "inventory", "users", "audit"};
        boolean validType = false;
        for (String t : allowedTypes) {
            if (t.equals(reportType)) { validType = true; break; }
        }
        if (!validType) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - sort column is validated, filter is parameterized... or is it?
        String baseQuery = "SELECT * FROM " + reportType + "_reports WHERE tenant_id = ?";

        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Developer thought: filter is just a column=value pair, parse it
            // BUG: directly concatenating user input into SQL
            baseQuery += " AND " + filterExpr;
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            // Sort column injection - ORDER BY cannot be parameterized
            baseQuery += " ORDER BY " + sortCol;
        }

        if (dateRange != null && !dateRange.isEmpty()) {
            baseQuery += " LIMIT 1000";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, tenantId);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Verbose error for debugging - leaks schema info
            resp.sendError(500, "Query failed: " + e.getMessage() + " | Query: " + baseQuery);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        JSONObject payload = new JSONObject(body.toString());
        String customQuery = payload.optString("query", "");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (tenantId == null) {
            resp.sendError(401);
            return;
        }

        // "Safe" custom query - just appends tenant filter
        String finalQuery = customQuery + " AND tenant_id = '" + tenantId + "'";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            ResultSet rs = stmt.executeQuery(finalQuery);
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }
            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Error: " + e.getMessage());
        }
    }
}
